pub fn show(text: &str, characters: &str) -> String {
    return format!(
        "[{}|{}|{}]",
        php_trim_chars(text, characters),
        php_ltrim_chars(text, characters),
        php_rtrim_chars(text, characters)
    );
}

fn php_charmask(characters: &str) -> [bool; 256] {
    let input = characters.as_bytes();
    let mut mask = [false; 256];
    let mut at = 0;
    while at < input.len() {
        let first = input[at];
        if at + 3 < input.len()
            && input[at + 1] == b'.'
            && input[at + 2] == b'.'
            && input[at + 3] >= first
        {
            for byte in first..=input[at + 3] {
                mask[usize::from(byte)] = true;
            }
            at += 4;
        } else if at + 1 < input.len() && first == b'.' && input[at + 1] == b'.' {
            at += 1;
        } else {
            mask[usize::from(first)] = true;
            at += 1;
        }
    }
    mask
}

fn php_trim_chars(text: &str, characters: &str) -> String {
    let mask = php_charmask(characters);
    let bytes = text.as_bytes();
    let start = bytes
        .iter()
        .position(|&byte| !mask[usize::from(byte)])
        .unwrap_or(bytes.len());
    let end = bytes
        .iter()
        .rposition(|&byte| !mask[usize::from(byte)])
        .map_or(start, |last| last + 1);
    String::from_utf8_lossy(&bytes[start..end]).into_owned()
}

fn php_ltrim_chars(text: &str, characters: &str) -> String {
    let mask = php_charmask(characters);
    let bytes = text.as_bytes();
    let start = bytes
        .iter()
        .position(|&byte| !mask[usize::from(byte)])
        .unwrap_or(bytes.len());
    String::from_utf8_lossy(&bytes[start..]).into_owned()
}

fn php_rtrim_chars(text: &str, characters: &str) -> String {
    let mask = php_charmask(characters);
    let bytes = text.as_bytes();
    let end = bytes
        .iter()
        .rposition(|&byte| !mask[usize::from(byte)])
        .map_or(0, |last| last + 1);
    String::from_utf8_lossy(&bytes[..end]).into_owned()
}

fn main() {
    let texts = vec![
        String::from(""),
        String::from("x"),
        String::from("xx"),
        String::from("xaxbx"),
        String::from("..ab.cXYz.."),
        String::from("\t a b \n"),
        String::from("\0zz\0"),
        String::from("abc"),
        String::from("é-é"),
        String::from("b..b"),
    ];
    let lists = vec![
        String::from(""),
        String::from("x"),
        String::from("xa"),
        String::from("a..c"),
        String::from("c..c."),
        String::from("."),
        String::from("X..Z."),
        String::from("...z"),
        String::from("\0..\u{1f}"),
        String::from(" a-z"),
        String::from("zz..zz"),
    ];
    for text in texts {
        for characters in lists.clone() {
            print!("{}", show(&text, &characters));
            print!("\n");
        }
    }
    print!("{}", php_trim_chars("--name--", "-"));
    print!(" ");
    print!("{}", php_ltrim_chars("0012", "0"));
    print!(" ");
    print!("{}", php_rtrim_chars("line\r\n", "\r\n"));
    print!("\n");
    print!("{}", php_trim_chars("abcHELLOcba", "a..c"));
    print!(" ");
    print!("{}", php_rtrim_chars("1.500", "0..9"));
    print!("\n");
}
